/**
 * Send one thing the caller said while recording in their browser: a finished phrase with when it started and ended, or that they began or stopped speaking. Times are the sender's clock; the server moves them onto its own from when the request arrived and sentAt. Only the person themselves may.
 * @summary Add narration to a recording in a person's own browser
 */

export const narrateInPersonBrowserPathPersonIdMax = 200;

export const narrateInPersonBrowserPathPersonIdRegExp = new RegExp("\\S");

export const NarrateInPersonBrowserParams = zod.object({
  organizationId: zod
    .string()
    .min(1)
    .describe(
      "The organization, by its id or its slug. One the caller is not a member of answers as one that does not exist, `default` included.",
    ),
  personId: zod
    .string()
    .min(1)
    .max(narrateInPersonBrowserPathPersonIdMax)
    .regex(narrateInPersonBrowserPathPersonIdRegExp)
    .describe(
      "The person: me for the caller, or a person's id. A person's own things (their instructions, preferences, API keys, sessions and linked accounts) answer only the person themselves, by either.",
    ),
});

export const narrateInPersonBrowserHeaderIdempotencyKeyMax = 128;

export const NarrateInPersonBrowserHeader = zod.object({
  "Idempotency-Key": zod
    .string()
    .min(1)
    .max(narrateInPersonBrowserHeaderIdempotencyKeyMax)
    .describe(
      "Generated by the caller for each write it means to make once. Reuse the same key and the same request for 24 hours after an uncertain response; the same key with a different request is a conflict.",
    ),
});

export const narrateInPersonBrowserBodyOneTextMax = 4000;

export const narrateInPersonBrowserBodyOneTextRegExp = new RegExp("\\S");
export const narrateInPersonBrowserBodyOneStartedAtMax = 8640000000000000;

export const narrateInPersonBrowserBodyOneEndedAtMax = 8640000000000000;

export const narrateInPersonBrowserBodyOneSentAtMax = 8640000000000000;

export const narrateInPersonBrowserBodyTwoSinceMax = 8640000000000000;

export const narrateInPersonBrowserBodyTwoSentAtMax = 8640000000000000;

export const narrateInPersonBrowserBodyThreeSentAtMax = 8640000000000000;

export const NarrateInPersonBrowserBody = zod
  .union([
    zod.object({
      text: zod
        .string()
        .min(1)
        .max(narrateInPersonBrowserBodyOneTextMax)
        .regex(narrateInPersonBrowserBodyOneTextRegExp)
        .describe("What the person said."),
      startedAt: zod
        .int()
        .min(1)
        .max(narrateInPersonBrowserBodyOneStartedAtMax)
        .describe(
          "A moment on the sender's clock, in milliseconds since 1970.",
        ),
      endedAt: zod
        .int()
        .min(1)
        .max(narrateInPersonBrowserBodyOneEndedAtMax)
        .describe(
          "A moment on the sender's clock, in milliseconds since 1970.",
        ),
      sentAt: zod
        .int()
        .min(1)
        .max(narrateInPersonBrowserBodyOneSentAtMax)
        .describe(
          "A moment on the sender's clock, in milliseconds since 1970.",
        ),
    }),
    zod.object({
      speaking: zod.literal(true),
      since: zod
        .int()
        .min(1)
        .max(narrateInPersonBrowserBodyTwoSinceMax)
        .describe(
          "A moment on the sender's clock, in milliseconds since 1970.",
        ),
      sentAt: zod
        .int()
        .min(1)
        .max(narrateInPersonBrowserBodyTwoSentAtMax)
        .describe(
          "A moment on the sender's clock, in milliseconds since 1970.",
        ),
    }),
    zod.object({
      speaking: zod.literal(false),
      sentAt: zod
        .int()
        .min(1)
        .max(narrateInPersonBrowserBodyThreeSentAtMax)
        .describe(
          "A moment on the sender's clock, in milliseconds since 1970.",
        ),
    }),
  ])
  .describe(
    "A finished phrase, or the person starting or stopping a phrase. sentAt is the sender's clock as the request leaves.",
  );

export const NarrateInPersonBrowserResponse = zod.object({
  ok: zod.literal(true),
});

